package dev.carcara.kotlinx.locale.codegen

import com.ibm.icu.number.NumberFormatter
import com.ibm.icu.number.Precision
import com.ibm.icu.util.Currency
import com.ibm.icu.util.ULocale
import java.io.File
import java.math.BigDecimal

/**
 * Goldens for the name form of a currency, generated by asking ICU4J to write
 * the same amounts at `UnitWidth.FULL_NAME`.
 *
 * The width the currency output goldens left a hole for. What it pins is the
 * whole composition and not just the table: which plural category the printed
 * number falls into, which of the six spellings that category reaches through
 * the `plural, other, display name, code` chain, which of the six patterns joins
 * the two, and the number written the way the locale writes a plain number
 * rather than the way it writes money.
 *
 * Two digit counts rather than one, and that is the point of the fixture. At
 * CLDR's own fraction digits almost every locale writes a visible `.00`, and
 * every rule that reads the operand `v` then lands on the same category: `one`,
 * `few` and `many` are unreachable and the golden would compare `other` twenty
 * thousand times. Asking for none as well is what makes `1 US dollar` and
 * `1 magyar forint` appear at all.
 */

/**
 * The locales the currency name goldens cover.
 *
 * The output goldens' set, plus locales chosen for their plural rules and for
 * what they do to the joining pattern. `ar cy br ga lt` reach five or six
 * categories between them, `ro` writes `{0} de {1}`, `sw` and `si` reorder the
 * two placeholders, and `ja` joins them with nothing at all.
 */
val ICU_CURRENCY_PLURAL_GOLDEN_LOCALES: List<String> = (
    ICU_CURRENCY_FORMAT_GOLDEN_LOCALES + listOf(
        "ro", "sw", "si", "cy", "br", "ga", "lt", "sk", "hr", "sl", "mt", "gd", "be", "ml", "or",
    )
    ).distinct()

/**
 * The amounts, as ISO minor units.
 *
 * Chosen against the plural rules rather than against the formatter: at no
 * fraction digits these are 0, 1, 2, 3, 5, 11, 21, 101 and 1234, which is enough
 * to separate every category any of the golden locales declares. Welsh alone
 * needs 0, 1, 2, 3 and 6 to show all six.
 */
val ICU_CURRENCY_PLURAL_GOLDEN_MINOR_UNITS: List<Long> = listOf(
    0, 100, 200, 300, 500, 600, 1100, 2100, 10100, 123400, -100, -123400,
)

/** One digit-count setting, and the name our side calls it by. */
class IcuCurrencyPluralPrecision(val name: String, val fractionDigits: Int?)

/**
 * The digit counts each amount is written at.
 *
 * `null` is CLDR's own count for the currency, which is what a caller who passes
 * no override gets.
 */
val ICU_CURRENCY_PLURAL_GOLDEN_PRECISIONS: List<IcuCurrencyPluralPrecision> = listOf(
    IcuCurrencyPluralPrecision("default", null),
    IcuCurrencyPluralPrecision("integer", 0),
)

/**
 * One locale's answers, plus the names they were produced from.
 *
 * The names travel with the output for the reason the currency output goldens
 * give: ICU 78.3 is built from a CLDR snapshot near but not identical to
 * `release-48-2`, so a name that moved between the two would report a data
 * difference as a formatting bug.
 */
class IcuCurrencyPluralGoldenEntry(
    val tag: String,
    /** `code|category` to the name ICU has for it, all six categories. */
    val names: Map<String, String>,
    /** `code|PRECISION` to answers, positional against [ICU_CURRENCY_PLURAL_GOLDEN_MINOR_UNITS]. */
    val answers: Map<String, List<String>>,
)

fun extractIcuCurrencyPluralGolden(isoMinorUnits: Map<String, Int>): List<IcuCurrencyPluralGoldenEntry> {
    // Same reason as the other ICU goldens: ICU resolves a locale it does not
    // carry against the default one, so an unpinned JVM would answer in whatever
    // the build machine happened to be set to.
    ULocale.setDefault(ULocale.ROOT)
    java.util.Locale.setDefault(java.util.Locale.ROOT)

    val available = ULocale.getAvailableLocales().mapTo(HashSet()) { it.toLanguageTag() }
    val missing = ArrayList<String>()
    val unanswerable = ArrayList<String>()
    val entries = ArrayList<IcuCurrencyPluralGoldenEntry>()

    for (cldrId in ICU_CURRENCY_PLURAL_GOLDEN_LOCALES) {
        val tag = canonicalTag(cldrId)
        if (tag !in available) {
            missing.add(tag)
            continue
        }
        val locale = ULocale.forLanguageTag(tag)
        val names = LinkedHashMap<String, String>()
        val answers = LinkedHashMap<String, List<String>>()

        for (code in ICU_CURRENCY_FORMAT_GOLDEN_CODES) {
            val currency = Currency.getInstance(code) ?: continue
            val digits = isoMinorUnits[code]?.takeIf { it >= 0 } ?: continue
            for (category in PLURAL_CATEGORIES) {
                names["$code|$category"] = currency.getName(locale, Currency.PLURAL_LONG_NAME, category, null) ?: code
            }
            for (precision in ICU_CURRENCY_PLURAL_GOLDEN_PRECISIONS) {
                var formatter = NumberFormatter.withLocale(locale).unit(currency)
                    .unitWidth(NumberFormatter.UnitWidth.FULL_NAME)
                precision.fractionDigits?.let { formatter = formatter.precision(Precision.fixedFraction(it)) }
                // ICU 78.3 cannot write every pair at this width. A currency that
                // declares a pattern of its own in a locale, which CLDR does once
                // for TRY in Turkish, routes the format through the pattern
                // modifier, and that modifier's switch over the widths throws on
                // FULL_NAME rather than handling it. It is an upstream defect and
                // not something to reproduce, so the pair is left out of the
                // fixture with the reason recorded.
                val written = runCatching {
                    ICU_CURRENCY_PLURAL_GOLDEN_MINOR_UNITS.map { minorUnits ->
                        formatter.format(BigDecimal.valueOf(minorUnits, digits)).toString()
                    }
                }.getOrElse {
                    unanswerable.add("$tag $code ${precision.name}")
                    continue
                }
                answers["$code|${precision.name}"] = written
            }
        }
        entries.add(IcuCurrencyPluralGoldenEntry(tag, names, answers))
    }

    val cells = entries.sumOf { it.answers.size } * ICU_CURRENCY_PLURAL_GOLDEN_MINOR_UNITS.size
    println(
        "[codegen] currency plural goldens cover ${entries.size} locales " +
            "(${ICU_CURRENCY_FORMAT_GOLDEN_CODES.size} currencies x ${ICU_CURRENCY_PLURAL_GOLDEN_PRECISIONS.size} digit counts " +
            "x ${ICU_CURRENCY_PLURAL_GOLDEN_MINOR_UNITS.size} amounts = $cells strings); " +
            "${missing.size} are absent from ICU4J; ICU cannot write ${unanswerable.size} pairs: $unanswerable",
    )
    check(entries.size >= 40) { "expected the currency plural goldens to cover at least 40 locales, got ${entries.size}" }
    check(unanswerable.size <= 4) {
        "ICU refused $unanswerable at this width. One currency with its own pattern is the known upstream defect; " +
            "more than that means something else changed."
    }
    return entries
}

fun emitIcuCurrencyPluralGolden(outputFile: File, icuTag: String, entries: List<IcuCurrencyPluralGoldenEntry>) {
    outputFile.parentFile.mkdirs()
    outputFile.writeText(
        buildString {
            append("// GENERATED by :codegen from ICU $icuTag. Do not edit.\n")
            append("// Regenerate with: ./gradlew :codegen:generateLocaleData\n")
            append("package dev.carcara.kotlinx.locale.currency.cldr.plurals.conformance\n\n")
            append("public const val ICU_CURRENCY_PLURAL_GOLDEN_VERSION: String = \"${kotlinEscape(icuTag)}\"\n\n")
            append("/** The amounts every record answers, in ISO minor units, in order. */\n")
            append("public val icuCurrencyPluralGoldenMinorUnits: List<Long> = listOf(\n")
            for (value in ICU_CURRENCY_PLURAL_GOLDEN_MINOR_UNITS) append("    ${value}L,\n")
            append(")\n\n")
            append("/** The digit-count settings the answers are keyed by, and the override each one means. */\n")
            append("public val icuCurrencyPluralGoldenPrecisions: Map<String, Int?> = mapOf(\n")
            for (precision in ICU_CURRENCY_PLURAL_GOLDEN_PRECISIONS) {
                append("    \"${kotlinEscape(precision.name)}\" to ${precision.fractionDigits},\n")
            }
            append(")\n\n")
            append("/**\n")
            append(" * One locale's answers: `code|category` to the name ICU has for it, and\n")
            append(" * `code|precision` to the strings it wrote.\n")
            append(" *\n")
            append(" * Both are held encoded and split on first use rather than written as map\n")
            append(" * literals, because the static initializer of the map form goes over the\n")
            append(" * JVM's 64 KB method limit.\n")
            append(" */\n")
            append("public class IcuCurrencyPluralGolden(private val encodedNames: String, private val encodedAnswers: String) {\n\n")
            append("    public val names: Map<String, String> by lazy {\n")
            append("        encodedNames.split('\\u001E').associate {\n")
            append("            val split = it.indexOf('\\u001D')\n")
            append("            it.substring(0, split) to it.substring(split + 1)\n")
            append("        }\n")
            append("    }\n\n")
            append("    public val answers: Map<String, List<String>> by lazy {\n")
            append("        encodedAnswers.split('\\u001E').associate {\n")
            append("            val split = it.indexOf('\\u001D')\n")
            append("            it.substring(0, split) to it.substring(split + 1).split('\\u001F')\n")
            append("        }\n")
            append("    }\n")
            append("}\n\n")
            append("/** Locale tag to its record. */\n")
            append("public val icuCurrencyPluralGoldenData: Map<String, IcuCurrencyPluralGolden> = buildMap(${entries.size}) {\n")
            for (entry in entries.sortedBy { it.tag }) {
                val names = entry.names.entries.joinToString(LIST_SEPARATOR) { (key, value) -> key + KEY_SEPARATOR + value }
                val answers = entry.answers.entries.joinToString(LIST_SEPARATOR) { (key, values) ->
                    key + KEY_SEPARATOR + values.joinToString(FIELD_SEPARATOR)
                }
                append("    put(\n")
                append("        \"${kotlinEscape(entry.tag)}\",\n")
                append("        IcuCurrencyPluralGolden(\n")
                append("            \"${kotlinEscape(names)}\",\n")
                append("            \"${kotlinEscape(answers)}\",\n")
                append("        ),\n")
                append("    )\n")
            }
            append("}\n")
        },
    )
    println("[codegen] emitted ${entries.size} ICU currency plural golden entries to $outputFile")
}
